package com.example.sgva.domain

/**
 * Indicador cuantitativo de calidad, resultado consolidado de los casos de uso
 * de los Módulos 1 y 2 (`DESIGN_SGVA.md` §1). Es el output principal que consume
 * el Dashboard.
 *
 * @property nombre nombre del indicador (ej.: "Tasa de Deserción", "Promedio Saber Pro").
 * @property valor resultado numérico calculado; debe ser un número finito.
 * @property periodo periodo académico `AAAAS` al que corresponde el valor, o
 *   [CONSOLIDADO] cuando el indicador agrega todos los periodos.
 * @property facultad facultad a la que corresponde, o [TODAS_LAS_FACULTADES]
 *   cuando el indicador no se filtró por facultad.
 */
data class IndicadorCalidad(
    val nombre: String,
    val valor: Double,
    val periodo: String,
    val facultad: String,
) {
    init {
        ReglasDeFormato.exigirNoVacio(nombre, "nombre")
        ReglasDeFormato.exigirNoVacio(periodo, "periodo")
        ReglasDeFormato.exigirNoVacio(facultad, "facultad")
        if (!valor.isFinite()) {
            throw ValorIndicadorInvalidoException(nombre, valor)
        }
    }

    companion object {
        /** Valor de [periodo] cuando el indicador agrega todos los periodos académicos. */
        const val CONSOLIDADO: String = "CONSOLIDADO"

        /** Valor de [facultad] cuando el indicador no se filtró por facultad. */
        const val TODAS_LAS_FACULTADES: String = "TODAS"

        /** Nombres canónicos de los indicadores del Módulo 1 (`DESIGN_SGVA.md` §1). */
        const val EVOLUCION_MATRICULA: String = "Evolución de Matrícula"
        const val TASA_DESERCION: String = "Tasa de Deserción"
        const val PROMEDIO_SABER_PRO: String = "Promedio Saber Pro"

        /** Nombres canónicos de los indicadores del Módulo 2 (`DESIGN_SGVA.md` §1). */
        const val DISTRIBUCION_FORMACION: String = "Distribución de Formación"
        const val RELACION_ESTUDIANTE_PROFESOR: String = "Relación Estudiante/Profesor"

        /** Nombre del indicador de distribución para un nivel de formación concreto. */
        fun distribucionFormacionPara(nivel: String): String = "$DISTRIBUCION_FORMACION - $nivel"
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.EstadoEstudiante
import com.example.sgva.domain.IndicadorCalidad
import com.example.sgva.domain.ParametrosDeAnalisis
import java.time.Clock
import java.time.LocalDate

/**
 * Módulo 1 — evolución de la matrícula (`DESIGN_SGVA.md` §2).
 *
 * Cuenta los estudiantes con estado [EstadoEstudiante.MATRICULADO] agrupados por
 * su cohorte (año + semestre) dentro de la ventana histórica de los últimos
 * [ParametrosDeAnalisis.ANIOS_VENTANA_MATRICULA] años calendario. La ventana se
 * calcula dinámicamente desde la fecha actual del sistema ([reloj]), nunca con
 * un rango fijo (`DESIGN_SGVA.md` §0.1).
 *
 * Devuelve un [IndicadorCalidad] por cada periodo de la ventana, en orden
 * ascendente, incluidos los periodos con valor `0` para que la serie temporal
 * del Dashboard sea continua.
 */
class CalcularEvolucionMatriculaUseCase(
    repositorio: AcademicDataRepository,
    private val reloj: Clock,
) : CalculoDeIndicadorUseCase(repositorio) {

    fun ejecutar(facultad: String? = null): List<IndicadorCalidad> {
        val matriculadosPorCohorte: Map<String, Int> = estudiantesRegistrados(facultad)
            .filter { it.estado == EstadoEstudiante.MATRICULADO }
            .groupBy { it.cohorte }
            .mapValues { (_, estudiantes) -> estudiantes.size }

        val etiqueta = etiquetaFacultad(facultad)
        return ventanaDePeriodos().map { periodo ->
            IndicadorCalidad(
                nombre = IndicadorCalidad.EVOLUCION_MATRICULA,
                valor = (matriculadosPorCohorte[periodo] ?: 0).toDouble(),
                periodo = periodo,
                facultad = etiqueta,
            )
        }
    }

    private fun ventanaDePeriodos(): List<String> {
        val anioActual = LocalDate.now(reloj).year
        val primerAnio = anioActual - ParametrosDeAnalisis.ANIOS_VENTANA_MATRICULA + 1
        return (primerAnio..anioActual)
            .flatMap { anio -> listOf("${anio}1", "${anio}2") }
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.EstadoEstudiante
import com.example.sgva.domain.IndicadorCalidad

/**
 * Módulo 1 — tasa de deserción (`DESIGN_SGVA.md` §2).
 *
 * Calcula el porcentaje de estudiantes en estado [EstadoEstudiante.DESERTOR]
 * frente al total de la cohorte seleccionada (todos los estados: matriculados,
 * graduados y desertores), opcionalmente restringido a una facultad.
 */
class CalcularTasaDesercionUseCase(
    repositorio: AcademicDataRepository,
) : CalculoDeIndicadorUseCase(repositorio) {

    /**
     * @param cohorte cohorte o periodo `AAAAS` a analizar.
     * @throws DatosInsuficientesException si no hay estudiantes en esa cohorte (el porcentaje sería indefinido).
     */
    fun ejecutar(cohorte: String, facultad: String? = null): IndicadorCalidad {
        val cohorteBuscada = cohorte.trim()
        val poblacion = estudiantesRegistrados(facultad).filter { it.cohorte == cohorteBuscada }

        if (poblacion.isEmpty()) {
            throw DatosInsuficientesException(
                "No hay estudiantes registrados para la cohorte '$cohorteBuscada'" +
                    (facultad?.let { " en la facultad '${it.trim()}'" } ?: "") + ".",
            )
        }

        val desertores = poblacion.count { it.estado == EstadoEstudiante.DESERTOR }
        return IndicadorCalidad(
            nombre = IndicadorCalidad.TASA_DESERCION,
            valor = redondearACentesimas(100.0 * desertores / poblacion.size),
            periodo = cohorteBuscada,
            facultad = etiquetaFacultad(facultad),
        )
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.IndicadorCalidad
import com.example.sgva.domain.NivelFormacion

/**
 * Módulo 2 — distribución de la formación docente (`DESIGN_SGVA.md` §2).
 *
 * Agrupa los docentes por [NivelFormacion] y calcula el porcentaje que
 * representa cada nivel sobre el total, opcionalmente restringido a un periodo
 * y/o una facultad. Devuelve un [IndicadorCalidad] por cada nivel de formación
 * (incluidos los de porcentaje `0`), en el orden del enum.
 */
class CalcularDistribucionFormacionUseCase(
    repositorio: AcademicDataRepository,
) : CalculoDeIndicadorUseCase(repositorio) {

    /**
     * @throws DatosInsuficientesException si no hay docentes registrados para el filtro dado.
     */
    fun ejecutar(periodo: String? = null, facultad: String? = null): List<IndicadorCalidad> {
        val docentes = docentesRegistrados(facultad, periodo)
        if (docentes.isEmpty()) {
            throw DatosInsuficientesException(
                "No hay docentes registrados para calcular la distribución de formación" +
                    descripcionFiltro(periodo, facultad) + ".",
            )
        }

        val conteoPorNivel = docentes.groupBy { it.nivelFormacion }.mapValues { it.value.size }
        val total = docentes.size
        val etiquetaPeriodo = etiquetaPeriodo(periodo)
        val etiquetaFacultad = etiquetaFacultad(facultad)

        return NivelFormacion.entries.map { nivel ->
            IndicadorCalidad(
                nombre = IndicadorCalidad.distribucionFormacionPara(nivel.name),
                valor = redondearACentesimas(100.0 * (conteoPorNivel[nivel] ?: 0) / total),
                periodo = etiquetaPeriodo,
                facultad = etiquetaFacultad,
            )
        }
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.EquivalenciaTiempoCompleto
import com.example.sgva.domain.EstadoEstudiante
import com.example.sgva.domain.IndicadorCalidad

/**
 * Módulo 2 — capacidad instalada / relación estudiantes-profesores
 * (`DESIGN_SGVA.md` §2).
 *
 * Calcula cuántos estudiantes matriculados hay por cada profesor de Tiempo
 * Completo Equivalente (TCE). El numerador son los estudiantes en estado
 * [EstadoEstudiante.MATRICULADO]; el denominador es la suma de los factores de
 * dedicación de los docentes ([EquivalenciaTiempoCompleto]). Ambos conjuntos se
 * pueden restringir por periodo (solo docentes) y por facultad.
 */
class CalcularCapacidadInstaladaUseCase(
    repositorio: AcademicDataRepository,
) : CalculoDeIndicadorUseCase(repositorio) {

    /**
     * @throws DatosInsuficientesException si no hay docentes (el denominador sería 0).
     */
    fun ejecutar(periodo: String? = null, facultad: String? = null): IndicadorCalidad {
        val matriculados = estudiantesRegistrados(facultad)
            .count { it.estado == EstadoEstudiante.MATRICULADO }

        val profesoresTce = docentesRegistrados(facultad, periodo)
            .sumOf { EquivalenciaTiempoCompleto.factor(it.dedicacion) }

        if (profesoresTce == 0.0) {
            throw DatosInsuficientesException(
                "No hay docentes registrados para calcular la relación estudiante/profesor" +
                    descripcionFiltro(periodo, facultad) + ".",
            )
        }

        return IndicadorCalidad(
            nombre = IndicadorCalidad.RELACION_ESTUDIANTE_PROFESOR,
            valor = redondearACentesimas(matriculados / profesoresTce),
            periodo = etiquetaPeriodo(periodo),
            facultad = etiquetaFacultad(facultad),
        )
    }
}

package com.example.sgva.domain

/** Máximo nivel de formación académica alcanzado por un [Docente]. */
enum class NivelFormacion {
    ESPECIALIZACION,
    MAESTRIA,
    DOCTORADO,
}

package com.example.sgva.domain

/** Tipo de dedicación contractual de un [Docente] con la institución. */
enum class TipoDedicacion {
    TIEMPO_COMPLETO,
    MEDIO_TIEMPO,
    CATEDRA,
}

